def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(range(10), key=lambda color: sum(cell == color for row in grid for cell in row))
    # Continue each maximal diagonal run of at least two equal non-background
    # cells in the run's direction, filling only empty/background cells.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                rr, cc, length = r, c, 1
                while 0 <= rr + dr < h and 0 <= cc + dc < w and grid[rr + dr][cc + dc] == color:
                    rr += dr
                    cc += dc
                    length += 1
                if length >= 2:
                    rr += dr
                    cc += dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
